1	//! In-process KV cache offload bridge between pegainfer and pegaflow.
2	//!
3	//! pegainfer owns the GPU paged-KV (`pegainfer-kv-cache::KvBuffer`, page-first
4	//! layout) and the logical prefix cache (kvbm `BlockPool`). pegaflow owns the
5	//! deeper tiers (host pinned memory, SSD, RDMA). [`OffloadEngine`] is the
6	//! connector "brain" that moves blocks between them and decides when.
7	//!
8	//! Dense-attention v1 (Qwen3-4B): the GPU prefix hit stays native to kvbm's
9	//! `BlockPool`; this connector covers the CPU tier and stacks a CPU-hit prefix
10	//! on top of the GPU-hit prefix (both anchor at prefix 0, so the combined hit
11	//! is one contiguous prefix split at a single point — GPU→CPU→GPU interleaving
12	//! is deliberately excluded). Save is best-effort fire-and-forget; load is on
13	//! the critical path, strongly ordered, but never blocks admission — every
14	//! operation resolves through a pollable [`OffloadHandle`] a request polls
15	//! each scheduler tick.
16	
17	mod config;
18	mod engine;
19	mod handle;
20	mod host;
21	mod layout;
22	mod vllm_hash;
23	
24	pub use config::OffloadConfig;
25	pub use config::P2pConfig;
26	pub use engine::OffloadEngine;
27	pub use handle::LoadHandle;
28	pub use handle::OffloadHandle;
29	pub use handle::QueryHit;
30	pub use handle::QueryOutcome;
31	pub use host::OffloadHost;
32	// Re-exported so callers name pegaflow's engine types through this bridge.
33	pub use pegaflow_core::{EngineError, PegaEngine, QueryLeaseId};
34	pub use vllm_hash::VllmBlockHasher;
